import { useState } from 'react';
import { useStore } from '../store/useStore';
import { CategoryCard } from '../components/CategoryCard';
import { TransactionType } from '../types';
import { formatCurrency } from '../utils/format';
import { Check, X } from 'lucide-react';

interface RecordProps {
  onSuccess: () => void;
}

export const Record = ({ onSuccess }: RecordProps) => {
  const [type, setType] = useState<TransactionType>('expense');
  const [amount, setAmount] = useState('');
  const [categoryId, setCategoryId] = useState<string | null>(null);
  const [note, setNote] = useState('');
  const [showSuccess, setShowSuccess] = useState(false);

  const categories = useStore((state) => state.categories);
  const addTransaction = useStore((state) => state.addTransaction);

  const filteredCategories = categories.filter((c) => c.type === type);

  const handleNumberClick = (num: string) => {
    if (num === '.') {
      if (!amount.includes('.')) {
        setAmount(amount + num);
      }
    } else if (num === 'del') {
      setAmount(amount.slice(0, -1));
    } else {
      if (amount.length < 12) {
        setAmount(amount + num);
      }
    }
  };

  const handleSubmit = () => {
    if (!amount || !categoryId) return;

    addTransaction({
      type,
      amount: parseFloat(amount),
      categoryId,
      note,
      createdAt: new Date().toISOString(),
    });

    setShowSuccess(true);
    setTimeout(() => {
      setShowSuccess(false);
      setAmount('');
      setCategoryId(null);
      setNote('');
      onSuccess();
    }, 1500);
  };

  const isFormValid = amount && categoryId;

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="bg-white p-6">
        <div className="flex items-center justify-center gap-4 mb-6">
          <button
            onClick={() => {
              setType('expense');
              setCategoryId(null);
            }}
            className={`px-6 py-2 rounded-full font-medium transition-all ${
              type === 'expense'
                ? 'bg-red-500 text-white scale-105'
                : 'bg-gray-100 text-gray-500'
            }`}
          >
            支出
          </button>
          <button
            onClick={() => {
              setType('income');
              setCategoryId(null);
            }}
            className={`px-6 py-2 rounded-full font-medium transition-all ${
              type === 'income'
                ? 'bg-emerald-500 text-white scale-105'
                : 'bg-gray-100 text-gray-500'
            }`}
          >
            收入
          </button>
        </div>

        <div className="text-center">
          <span className="text-gray-400 text-xl">¥</span>
          <span className="text-5xl font-bold text-gray-800 ml-1">
            {amount || '0.00'}
          </span>
        </div>
      </div>

      <div className="bg-white mt-2 p-4">
        <h3 className="text-sm font-medium text-gray-500 mb-3">选择分类</h3>
        <div className="grid grid-cols-4 gap-2">
          {filteredCategories.map((category) => (
            <CategoryCard
              key={category.id}
              category={category}
              isSelected={categoryId === category.id}
              onClick={() => setCategoryId(category.id)}
            />
          ))}
        </div>
      </div>

      <div className="bg-white mt-2 p-4">
        <input
          type="text"
          placeholder="添加备注（可选）"
          value={note}
          onChange={(e) => setNote(e.target.value)}
          className="w-full px-4 py-3 bg-gray-50 rounded-xl text-gray-800 placeholder-gray-400 outline-none focus:ring-2 focus:ring-emerald-500/20"
          maxLength={50}
        />
      </div>

      <div className="mt-6 px-4">
        <button
          onClick={handleSubmit}
          disabled={!isFormValid}
          className={`w-full py-4 rounded-xl font-semibold text-lg transition-all ${
            isFormValid
              ? 'bg-gradient-to-r from-emerald-500 to-green-600 text-white hover:shadow-lg hover:shadow-emerald-500/30'
              : 'bg-gray-200 text-gray-400 cursor-not-allowed'
          }`}
        >
          保存记录
        </button>
      </div>

      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 p-4">
        <div className="grid grid-cols-3 gap-2">
          {['1', '2', '3'].map((num) => (
            <button
              key={num}
              onClick={() => handleNumberClick(num)}
              className="py-4 bg-gray-100 rounded-xl font-semibold text-xl text-gray-800 active:bg-gray-200"
            >
              {num}
            </button>
          ))}
          {['4', '5', '6'].map((num) => (
            <button
              key={num}
              onClick={() => handleNumberClick(num)}
              className="py-4 bg-gray-100 rounded-xl font-semibold text-xl text-gray-800 active:bg-gray-200"
            >
              {num}
            </button>
          ))}
          {['7', '8', '9'].map((num) => (
            <button
              key={num}
              onClick={() => handleNumberClick(num)}
              className="py-4 bg-gray-100 rounded-xl font-semibold text-xl text-gray-800 active:bg-gray-200"
            >
              {num}
            </button>
          ))}
          <button
            onClick={() => handleNumberClick('del')}
            className="py-4 bg-gray-100 rounded-xl font-semibold text-xl text-gray-500 active:bg-gray-200 flex items-center justify-center"
          >
            <X size={24} />
          </button>
          <button
            onClick={() => handleNumberClick('0')}
            className="py-4 bg-gray-100 rounded-xl font-semibold text-xl text-gray-800 active:bg-gray-200"
          >
            0
          </button>
          <button
            onClick={() => handleNumberClick('.')}
            className="py-4 bg-gray-100 rounded-xl font-semibold text-xl text-gray-800 active:bg-gray-200"
          >
            .
          </button>
        </div>
      </div>

      {showSuccess && (
        <div className="fixed inset-0 bg-black/30 flex items-center justify-center z-50">
          <div className="bg-white rounded-2xl p-8 text-center animate-bounce-in">
            <div className="w-16 h-16 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <Check size={32} className="text-emerald-500" />
            </div>
            <p className="text-xl font-semibold text-gray-800">记录成功</p>
          </div>
        </div>
      )}
    </div>
  );
};