import { create } from 'zustand';
import { Category, Transaction } from '../types';
import { initialCategories, initialTransactions } from '../data/initialData';
import { loadTransactions, saveTransactions, loadCategories, saveCategories } from '../utils/storage';

interface Store {
  transactions: Transaction[];
  categories: Category[];
  addTransaction: (transaction: Omit<Transaction, 'id'>) => void;
  deleteTransaction: (id: string) => void;
  addCategory: (category: Omit<Category, 'id'>) => void;
  deleteCategory: (id: string) => void;
  getCategoryById: (id: string) => Category | undefined;
  getTodayIncome: () => number;
  getTodayExpense: () => number;
  getMonthIncome: () => number;
  getMonthExpense: () => number;
  getTransactionsByMonth: (month: number, year: number) => Transaction[];
  getTransactionsGroupedByCategory: (type: 'income' | 'expense') => { category: Category; total: number }[];
}

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

export const useStore = create<Store>((set, get) => ({
  transactions: loadTransactions(initialTransactions),
  categories: loadCategories(initialCategories),

  addTransaction: (transaction) => {
    const newTransaction: Transaction = {
      ...transaction,
      id: generateId(),
    };
    set((state) => {
      const updated = [...state.transactions, newTransaction];
      saveTransactions(updated);
      return { transactions: updated };
    });
  },

  deleteTransaction: (id) => {
    set((state) => {
      const updated = state.transactions.filter((t) => t.id !== id);
      saveTransactions(updated);
      return { transactions: updated };
    });
  },

  addCategory: (category) => {
    const newCategory: Category = {
      ...category,
      id: generateId(),
    };
    set((state) => {
      const updated = [...state.categories, newCategory];
      saveCategories(updated);
      return { categories: updated };
    });
  },

  deleteCategory: (id) => {
    set((state) => {
      const updated = state.categories.filter((c) => c.id !== id);
      saveCategories(updated);
      return { categories: updated };
    });
  },

  getCategoryById: (id) => {
    return get().categories.find((c) => c.id === id);
  },

  getTodayIncome: () => {
    const today = new Date().toISOString().split('T')[0];
    return get().transactions
      .filter((t) => t.type === 'income' && t.createdAt.startsWith(today))
      .reduce((sum, t) => sum + t.amount, 0);
  },

  getTodayExpense: () => {
    const today = new Date().toISOString().split('T')[0];
    return get().transactions
      .filter((t) => t.type === 'expense' && t.createdAt.startsWith(today))
      .reduce((sum, t) => sum + t.amount, 0);
  },

  getMonthIncome: () => {
    const now = new Date();
    const month = now.getMonth();
    const year = now.getFullYear();
    return get().transactions
      .filter((t) => {
        const date = new Date(t.createdAt);
        return t.type === 'income' && date.getMonth() === month && date.getFullYear() === year;
      })
      .reduce((sum, t) => sum + t.amount, 0);
  },

  getMonthExpense: () => {
    const now = new Date();
    const month = now.getMonth();
    const year = now.getFullYear();
    return get().transactions
      .filter((t) => {
        const date = new Date(t.createdAt);
        return t.type === 'expense' && date.getMonth() === month && date.getFullYear() === year;
      })
      .reduce((sum, t) => sum + t.amount, 0);
  },

  getTransactionsByMonth: (month, year) => {
    return get().transactions.filter((t) => {
      const date = new Date(t.createdAt);
      return date.getMonth() === month && date.getFullYear() === year;
    });
  },

  getTransactionsGroupedByCategory: (type) => {
    const transactions = get().transactions.filter((t) => t.type === type);
    const grouped: Record<string, number> = {};

    transactions.forEach((t) => {
      grouped[t.categoryId] = (grouped[t.categoryId] || 0) + t.amount;
    });

    return Object.entries(grouped)
      .map(([categoryId, total]) => ({
        category: get().getCategoryById(categoryId)!,
        total,
      }))
      .sort((a, b) => b.total - a.total);
  },
}));