import { useState } from 'react';
import * as Icons from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { useStore } from '../store/useStore';
import { Category, TransactionType } from '../types';
import { Plus, X, ChevronRight } from 'lucide-react';

const iconMap: Record<string, LucideIcon> = Icons as unknown as Record<string, LucideIcon>;

export const Categories = () => {
  const [showAddModal, setShowAddModal] = useState(false);
  const [newCategory, setNewCategory] = useState({
    name: '',
    type: 'expense' as TransactionType,
    icon: 'Circle',
    color: '#EF4444',
  });

  const categories = useStore((state) => state.categories);
  const addCategory = useStore((state) => state.addCategory);
  const deleteCategory = useStore((state) => state.deleteCategory);

  const incomeCategories = categories.filter((c) => c.type === 'income');
  const expenseCategories = categories.filter((c) => c.type === 'expense');

  const iconList = [
    'Wallet', 'Gift', 'TrendingUp', 'Plus', 'Briefcase', 'Award',
    'UtensilsCrossed', 'Car', 'ShoppingBag', 'Gamepad2', 'Heart',
    'GraduationCap', 'Home', 'MoreHorizontal', 'Coffee', 'Plane',
    'Shirt', 'Music', 'BookOpen', 'Phone', 'Laptop', 'Camera',
  ];

  const colorList = [
    '#EF4444', '#F97316', '#F59E0B', '#EAB308', '#84CC16', '#22C55E',
    '#10B981', '#14B8A6', '#06B6D4', '#0EA5E9', '#3B82F6', '#6366F1',
    '#8B5CF6', '#A855F7', '#D946EF', '#EC4899', '#F43F5E',
  ];

  const handleAddCategory = () => {
    if (!newCategory.name.trim()) return;
    addCategory(newCategory);
    setShowAddModal(false);
    setNewCategory({
      name: '',
      type: 'expense',
      icon: 'Circle',
      color: '#EF4444',
    });
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      <div className="bg-white p-6">
        <h1 className="text-2xl font-bold text-gray-800">分类管理</h1>
        <p className="text-gray-400 text-sm mt-1">管理您的收支分类</p>
      </div>

      <div className="px-4 mt-4">
        <div className="bg-white rounded-xl p-4">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-semibold text-gray-800 flex items-center gap-2">
              <span className="w-2 h-2 bg-red-500 rounded-full"></span>
              支出分类
            </h2>
            <button
              onClick={() => {
                setNewCategory((prev) => ({ ...prev, type: 'expense' }));
                setShowAddModal(true);
              }}
              className="p-2 text-gray-400 hover:text-emerald-500 hover:bg-emerald-50 rounded-lg transition-colors"
            >
              <Plus size={20} />
            </button>
          </div>
          <div className="grid grid-cols-4 gap-3">
            {expenseCategories.map((category) => {
              const IconComponent = iconMap[category.icon] || Icons.Circle;
              return (
                <div
                  key={category.id}
                  className="flex flex-col items-center p-3 bg-gray-50 rounded-xl relative group"
                >
                  <button
                    onClick={() => deleteCategory(category.id)}
                    className="absolute -top-1 -right-1 p-1 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <X size={12} />
                  </button>
                  <div
                    className="p-2.5 rounded-full"
                    style={{ backgroundColor: `${category.color}20` }}
                  >
                    <IconComponent size={20} style={{ color: category.color }} />
                  </div>
                  <span className="text-xs mt-2 font-medium text-gray-600">
                    {category.name}
                  </span>
                </div>
              );
            })}
          </div>
        </div>

        <div className="bg-white rounded-xl p-4 mt-4">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-semibold text-gray-800 flex items-center gap-2">
              <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
              收入分类
            </h2>
            <button
              onClick={() => {
                setNewCategory((prev) => ({ ...prev, type: 'income' }));
                setShowAddModal(true);
              }}
              className="p-2 text-gray-400 hover:text-emerald-500 hover:bg-emerald-50 rounded-lg transition-colors"
            >
              <Plus size={20} />
            </button>
          </div>
          <div className="grid grid-cols-4 gap-3">
            {incomeCategories.map((category) => {
              const IconComponent = iconMap[category.icon] || Icons.Circle;
              return (
                <div
                  key={category.id}
                  className="flex flex-col items-center p-3 bg-gray-50 rounded-xl relative group"
                >
                  <button
                    onClick={() => deleteCategory(category.id)}
                    className="absolute -top-1 -right-1 p-1 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <X size={12} />
                  </button>
                  <div
                    className="p-2.5 rounded-full"
                    style={{ backgroundColor: `${category.color}20` }}
                  >
                    <IconComponent size={20} style={{ color: category.color }} />
                  </div>
                  <span className="text-xs mt-2 font-medium text-gray-600">
                    {category.name}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-end justify-center z-50">
          <div className="bg-white w-full rounded-t-3xl p-6 max-h-[80vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-semibold text-gray-800">添加分类</h3>
              <button
                onClick={() => setShowAddModal(false)}
                className="p-2 text-gray-400 hover:text-gray-600"
              >
                <X size={24} />
              </button>
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-600 mb-2">
                分类名称
              </label>
              <input
                type="text"
                value={newCategory.name}
                onChange={(e) => setNewCategory((prev) => ({ ...prev, name: e.target.value }))}
                className="w-full px-4 py-3 bg-gray-50 rounded-xl text-gray-800 placeholder-gray-400 outline-none focus:ring-2 focus:ring-emerald-500/20"
                placeholder="输入分类名称"
                maxLength={10}
              />
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-600 mb-2">
                选择图标
              </label>
              <div className="grid grid-cols-6 gap-2">
                {iconList.map((icon) => {
                  const IconComponent = iconMap[icon] || Icons.Circle;
                  return (
                    <button
                      key={icon}
                      onClick={() => setNewCategory((prev) => ({ ...prev, icon }))}
                      className={`p-2 rounded-xl transition-all ${
                        newCategory.icon === icon
                          ? 'bg-emerald-100 text-emerald-600'
                          : 'bg-gray-100 text-gray-500 hover:bg-gray-200'
                      }`}
                    >
                      <IconComponent size={20} />
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-600 mb-2">
                选择颜色
              </label>
              <div className="flex flex-wrap gap-2">
                {colorList.map((color) => (
                  <button
                    key={color}
                    onClick={() => setNewCategory((prev) => ({ ...prev, color }))}
                    className={`w-8 h-8 rounded-full transition-all ${
                      newCategory.color === color ? 'ring-2 ring-offset-2 ring-gray-400 scale-110' : ''
                    }`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            </div>

            <button
              onClick={handleAddCategory}
              disabled={!newCategory.name.trim()}
              className={`w-full py-4 rounded-xl font-semibold text-lg transition-all ${
                newCategory.name.trim()
                  ? 'bg-gradient-to-r from-emerald-500 to-green-600 text-white'
                  : 'bg-gray-200 text-gray-400 cursor-not-allowed'
              }`}
            >
              添加分类
            </button>
          </div>
        </div>
      )}
    </div>
  );
};