import * as Icons from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { Transaction } from '../types';
import { useStore } from '../store/useStore';
import { formatCurrency, formatDate } from '../utils/format';
import { Trash2 } from 'lucide-react';

interface TransactionCardProps {
  transaction: Transaction;
  onDelete?: () => void;
}

const iconMap: Record<string, LucideIcon> = Icons as unknown as Record<string, LucideIcon>;

export const TransactionCard = ({ transaction, onDelete }: TransactionCardProps) => {
  const category = useStore((state) => state.getCategoryById(transaction.categoryId));
  const IconComponent = category
    ? iconMap[category.icon] || Icons.Circle
    : Icons.Circle;

  const isIncome = transaction.type === 'income';

  return (
    <div className="flex items-center justify-between p-4 bg-white rounded-xl hover:bg-gray-50 transition-colors">
      <div className="flex items-center gap-3">
        <div
          className="p-2.5 rounded-full"
          style={{ backgroundColor: category ? `${category.color}20` : '#f3f4f6' }}
        >
          <IconComponent
            size={20}
            style={{ color: category?.color || '#9ca3af' }}
          />
        </div>
        <div>
          <p className="font-medium text-gray-800">{category?.name || '未知'}</p>
          {transaction.note && (
            <p className="text-sm text-gray-400 mt-0.5">{transaction.note}</p>
          )}
        </div>
      </div>
      <div className="flex items-center gap-3">
        <span className="text-sm text-gray-400">
          {formatDate(transaction.createdAt)}
        </span>
        <span
          className={`font-semibold ${
            isIncome ? 'text-emerald-600' : 'text-red-500'
          }`}
        >
          {isIncome ? '+' : '-'}¥{formatCurrency(transaction.amount)}
        </span>
        {onDelete && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              onDelete();
            }}
            className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
          >
            <Trash2 size={16} />
          </button>
        )}
      </div>
    </div>
  );
};