import { useState } from 'react';
import { Dashboard } from './pages/Dashboard';
import { Record } from './pages/Record';
import { Categories } from './pages/Categories';
import { Statistics } from './pages/Statistics';
import { BottomNav } from './components/BottomNav';

export default function App() {
  const [currentPage, setCurrentPage] = useState('/');

  const handleAddRecord = () => {
    setCurrentPage('/record');
  };

  const handleRecordSuccess = () => {
    setCurrentPage('/');
  };

  const renderPage = () => {
    switch (currentPage) {
      case '/':
        return <Dashboard onAddRecord={handleAddRecord} />;
      case '/record':
        return <Record onSuccess={handleRecordSuccess} />;
      case '/categories':
        return <Categories />;
      case '/statistics':
        return <Statistics />;
      default:
        return <Dashboard onAddRecord={handleAddRecord} />;
    }
  };

  const showBottomNav = currentPage !== '/record';

  return (
    <div className="min-h-screen bg-gray-50">
      {renderPage()}
      {showBottomNav && <BottomNav currentPage={currentPage} onPageChange={setCurrentPage} />}
    </div>
  );
}