import { useState } from 'react';
import { useStore } from '../store/useStore';
import { formatCurrency } from '../utils/format';
import { PieChart, Pie, Cell, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { Calendar } from 'lucide-react';

export const Statistics = () => {
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth());
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

  const monthIncome = useStore((state) => state.getMonthIncome());
  const monthExpense = useStore((state) => state.getMonthExpense());
  const getTransactionsGroupedByCategory = useStore((state) => state.getTransactionsGroupedByCategory);

  const expenseData = getTransactionsGroupedByCategory('expense');
  const incomeData = getTransactionsGroupedByCategory('income');

  const months = [
    '1月', '2月', '3月', '4月', '5月', '6月',
    '7月', '8月', '9月', '10月', '11月', '12月'
  ];

  const years = Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - i);

  const generateMonthlyData = () => {
    const data = [];
    for (let i = 11; i >= 0; i--) {
      const date = new Date();
      date.setMonth(date.getMonth() - i);
      const month = date.getMonth();
      const year = date.getFullYear();
      
      let income = 0;
      let expense = 0;
      
      useStore.getState().transactions.forEach((t) => {
        const tDate = new Date(t.createdAt);
        if (tDate.getMonth() === month && tDate.getFullYear() === year) {
          if (t.type === 'income') {
            income += t.amount;
          } else {
            expense += t.amount;
          }
        }
      });
      
      data.push({
        month: months[month],
        income,
        expense,
      });
    }
    return data;
  };

  const monthlyChartData = generateMonthlyData();

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      <div className="bg-gradient-to-br from-emerald-500 to-green-600 text-white p-6 rounded-b-3xl">
        <h1 className="text-2xl font-bold">统计报表</h1>
        <p className="text-emerald-100 text-sm mt-1">查看您的财务数据</p>
      </div>

      <div className="px-4 -mt-4">
        <div className="bg-white rounded-xl shadow-lg p-4">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              <Calendar size={20} className="text-gray-400" />
              <select
                value={selectedYear}
                onChange={(e) => setSelectedYear(Number(e.target.value))}
                className="bg-gray-50 px-3 py-2 rounded-lg text-gray-800 outline-none"
              >
                {years.map((year) => (
                  <option key={year} value={year}>{year}年</option>
                ))}
              </select>
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="bg-gray-50 px-3 py-2 rounded-lg text-gray-800 outline-none"
              >
                {months.map((month, index) => (
                  <option key={index} value={index}>{month}</option>
                ))}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="text-center p-4 bg-emerald-50 rounded-xl">
              <p className="text-gray-500 text-sm">本月收入</p>
              <p className="text-2xl font-bold text-emerald-600 mt-1">
                ¥{formatCurrency(monthIncome)}
              </p>
            </div>
            <div className="text-center p-4 bg-red-50 rounded-xl">
              <p className="text-gray-500 text-sm">本月支出</p>
              <p className="text-2xl font-bold text-red-500 mt-1">
                ¥{formatCurrency(monthExpense)}
              </p>
            </div>
          </div>

          <div className="mt-4 p-4 bg-gray-50 rounded-xl">
            <p className="text-gray-500 text-sm text-center">本月结余</p>
            <p className={`text-3xl font-bold text-center mt-1 ${
              monthIncome - monthExpense >= 0 ? 'text-emerald-600' : 'text-red-500'
            }`}>
              ¥{formatCurrency(monthIncome - monthExpense)}
            </p>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-lg p-4 mt-4">
          <h2 className="font-semibold text-gray-800 mb-4">支出分布</h2>
          {expenseData.length > 0 ? (
            <ResponsiveContainer width="100%" height={200}>
              <PieChart>
                <Pie
                  data={expenseData.map((item) => ({
                    name: item.category.name,
                    value: item.total,
                    color: item.category.color,
                  }))}
                  cx="50%"
                  cy="50%"
                  innerRadius={50}
                  outerRadius={80}
                  paddingAngle={2}
                  dataKey="value"
                  label={({ name, percent }) => `${name} ${(percent * 100).toFixed(1)}%`}
                >
                  {expenseData.map((item, index) => (
                    <Cell key={`cell-${index}`} fill={item.category.color} />
                  ))}
                </Pie>
                <Tooltip
                  formatter={(value: number) => [`¥${formatCurrency(value)}`, '']}
                />
              </PieChart>
            </ResponsiveContainer>
          ) : (
            <div className="text-center py-8 text-gray-400">
              暂无支出数据
            </div>
          )}
        </div>

        <div className="bg-white rounded-xl shadow-lg p-4 mt-4">
          <h2 className="font-semibold text-gray-800 mb-4">收入分布</h2>
          {incomeData.length > 0 ? (
            <ResponsiveContainer width="100%" height={200}>
              <PieChart>
                <Pie
                  data={incomeData.map((item) => ({
                    name: item.category.name,
                    value: item.total,
                    color: item.category.color,
                  }))}
                  cx="50%"
                  cy="50%"
                  innerRadius={50}
                  outerRadius={80}
                  paddingAngle={2}
                  dataKey="value"
                  label={({ name, percent }) => `${name} ${(percent * 100).toFixed(1)}%`}
                >
                  {incomeData.map((item, index) => (
                    <Cell key={`cell-${index}`} fill={item.category.color} />
                  ))}
                </Pie>
                <Tooltip
                  formatter={(value: number) => [`¥${formatCurrency(value)}`, '']}
                />
              </PieChart>
            </ResponsiveContainer>
          ) : (
            <div className="text-center py-8 text-gray-400">
              暂无收入数据
            </div>
          )}
        </div>

        <div className="bg-white rounded-xl shadow-lg p-4 mt-4">
          <h2 className="font-semibold text-gray-800 mb-4">收支趋势</h2>
          <ResponsiveContainer width="100%" height={250}>
            <BarChart data={monthlyChartData}>
              <XAxis dataKey="month" />
              <YAxis />
              <Tooltip
                formatter={(value: number) => [`¥${formatCurrency(value)}`, '']}
              />
              <Legend />
              <Bar dataKey="income" name="收入" fill="#10B981" radius={[4, 4, 0, 0]} />
              <Bar dataKey="expense" name="支出" fill="#EF4444" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};