import { useStore } from '../store/useStore';
import { StatCard } from '../components/StatCard';
import { TransactionCard } from '../components/TransactionCard';
import { formatCurrency } from '../utils/format';
import { Wallet } from 'lucide-react';

interface DashboardProps {
  onAddRecord: () => void;
}

export const Dashboard = ({ onAddRecord }: DashboardProps) => {
  const transactions = useStore((state) => state.transactions);
  const deleteTransaction = useStore((state) => state.deleteTransaction);
  const todayIncome = useStore((state) => state.getTodayIncome());
  const todayExpense = useStore((state) => state.getTodayExpense());
  const monthIncome = useStore((state) => state.getMonthIncome());
  const monthExpense = useStore((state) => state.getMonthExpense());

  const recentTransactions = [...transactions]
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
    .slice(0, 5);

  const balance = monthIncome - monthExpense;

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      <div className="bg-gradient-to-br from-emerald-500 to-green-600 text-white p-6 rounded-b-3xl">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h1 className="text-2xl font-bold">财务概览</h1>
            <p className="text-emerald-100 text-sm mt-1">
              {new Date().toLocaleDateString('zh-CN', {
                year: 'numeric',
                month: 'long',
                day: 'numeric',
              })}
            </p>
          </div>
          <div className="bg-white/20 p-3 rounded-full">
            <Wallet size={28} />
          </div>
        </div>
        <div className="bg-white/10 backdrop-blur-sm rounded-2xl p-4">
          <p className="text-emerald-100 text-sm">本月余额</p>
          <p className="text-3xl font-bold mt-1">¥{formatCurrency(balance)}</p>
        </div>
      </div>

      <div className="px-4 mt-4">
        <div className="grid grid-cols-2 gap-3">
          <StatCard type="income" title="今日收入" amount={todayIncome} />
          <StatCard type="expense" title="今日支出" amount={todayExpense} />
        </div>

        <div className="grid grid-cols-2 gap-3 mt-3">
          <StatCard type="income" title="本月收入" amount={monthIncome} />
          <StatCard type="expense" title="本月支出" amount={monthExpense} />
        </div>
      </div>

      <div className="px-4 mt-6">
        <div className="flex items-center justify-between mb-3">
          <h2 className="font-semibold text-gray-800">最近记录</h2>
          <button
            onClick={onAddRecord}
            className="text-emerald-500 text-sm font-medium hover:text-emerald-600"
          >记一笔</button>
        </div>
        
        {recentTransactions.length === 0 ? (
          <div className="text-center py-12 text-gray-400">
            <p>暂无记录</p>
            <button
              onClick={onAddRecord}
              className="mt-4 px-6 py-2 bg-emerald-500 text-white rounded-full text-sm font-medium"
            >
              添加第一笔记录
            </button>
          </div>
        ) : (
          <div className="space-y-2">
            {recentTransactions.map((transaction) => (
              <TransactionCard
                key={transaction.id}
                transaction={transaction}
                onDelete={() => deleteTransaction(transaction.id)}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};